"""Part C. Synthetic patients. No names. Expected behaviour assumes the recommended option of every D-REL decision.

place: leading | coexisting | linked | differential | background | deferred
A 'linked' item sits under the diagnosis named in relation.to (shown on the higher-placed of the two; see design §2.3).
relation types: due_to (label complication | secondary | precipitated_by), associated_with, risk_factor_for (derived line), episode_of
"""

def dx(id, place, verification="provisional", status="working", relation=None, stage=None, qualifier=None, note=None):
    out = dict(id=id, place=place, verification=verification, status=status)
    if relation: out["relation"] = relation
    if stage: out["stage"] = stage
    if qualifier: out["qualifier"] = qualifier
    if note: out["note"] = note
    return out

def rel(type, to, label=None):
    r = dict(type=type, to=to)
    if label: r["label"] = label
    return r

